#include "simulator.h"
#include "framecodec.h"
#include <QRandomGenerator>
#include <QUuid>
Simulator::Simulator(const QString&code,QObject*p):QObject(p),m_code(code){m_heartbeat.setInterval(5000);m_telemetry.setInterval(2000);connect(&m_heartbeat,&QTimer::timeout,this,&Simulator::heartbeat);connect(&m_telemetry,&QTimer::timeout,this,&Simulator::telemetry);connect(&m_socket,&QTcpSocket::connected,this,[this]{m_heartbeat.start();m_telemetry.start();heartbeat();});connect(&m_socket,&QTcpSocket::disconnected,this,&Simulator::reconnect);}
void Simulator::start(const QString&host,quint16 port){m_socket.setProperty("host",host);m_socket.setProperty("port",port);m_socket.connectToHost(host,port);}void Simulator::reconnect(){m_heartbeat.stop();m_telemetry.stop();QTimer::singleShot(3000,this,[this]{m_socket.connectToHost(m_socket.property("host").toString(),static_cast<quint16>(m_socket.property("port").toUInt()));});}void Simulator::send(const QString&t,const QJsonObject&p){if(m_socket.state()==QTcpSocket::ConnectedState)m_socket.write(Protocol::encode(Protocol::request(t,p,QUuid::createUuid().toString(QUuid::WithoutBraces))));}void Simulator::heartbeat(){send("device.heartbeat",{{"chargerCode",m_code},{"status","IDLE"}});}void Simulator::telemetry(){const double current=30.0+QRandomGenerator::global()->bounded(1000)/100.0;const double voltage=380.0+QRandomGenerator::global()->bounded(500)/100.0;const double power=voltage*current/1000.0;m_soc=qMin(100.0,m_soc+0.05);send("device.telemetry",{{"chargerCode",m_code},{"voltage",voltage},{"current",current},{"power",power},{"soc",m_soc}});}

